# 2. Header verification
curl -I http://127.0.0.1:7890/health
# Expected: HTTP/1.1 200 OK + Content-Type: application/json

# 3. Method constraint verification
curl -X POST http://127.0.0.1:7890/health
# Expected: 405 or 404 (not 500 or HTML error)

# 4. Cache behavior verification
curl -s -H "Cache-Control: max-age=60" http://127.0.0.1:7890/health
# Expected: No caching (response should vary per request due to timestamp)

# 5. JSON validity verification
curl -s http://127.0.0.1:7890/health | python3 -m json.tool > /dev/null && echo "JSON valid"
# Expected: "JSON valid"
```

